import{at as e,it as t,n,vt as r}from"./chunks/framework.DbV_8hbX.js";var i=JSON.parse(`{"title":"Set up on Cloudflare","description":"","frontmatter":{},"headers":[],"relativePath":"en/getting-started/cloudflare.md","filePath":"en/getting-started/cloudflare.md","lastUpdated":1794405696000}`),a={name:`en/getting-started/cloudflare.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="set-up-on-cloudflare" tabindex="-1">Set up on Cloudflare <a class="header-anchor" href="#set-up-on-cloudflare" aria-label="Permalink to “Set up on Cloudflare”">​</a></h1><p>Workers run the admin console, SDK and API. D1 holds the admin data, and Durable Objects hold Jev&#39;s cost counter. This setup does not store visitors&#39; behavior history in D1.</p><h2 id="what-you-need" tabindex="-1">What you need <a class="header-anchor" href="#what-you-need" aria-label="Permalink to “What you need”">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Purpose</th></tr></thead><tbody><tr><td>A Cloudflare account</td><td>Workers, D1, Durable Objects and Access</td></tr><tr><td>The GitHub code and Node.js 24 or later</td><td>Build and deployment</td></tr><tr><td>A Cloudflare API token</td><td>Permissions to update Workers, edit D1 and configure Access on your account</td></tr><tr><td>A Jev API key</td><td>Real judgments in production. Not needed while you check Preview with the stub</td></tr><tr><td>A stable admin console origin</td><td>Where passkeys are registered. HTTPS workers.dev works too</td></tr></tbody></table><p>If you are using Access for the first time, also complete the initial Cloudflare Zero Trust setup. Check pricing, available features and limits against your own plan.</p><h2 id="_1-get-the-code" tabindex="-1">1. Get the code <a class="header-anchor" href="#_1-get-the-code" aria-label="Permalink to “1. Get the code”">​</a></h2><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/manji6/jev-personalization.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> jev-personalization</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">Don&#39;t deploy the repository&#39;s settings as they are</p><p><code>wrangler.json</code> contains the developer&#39;s Worker, account, database and Access settings. Replace the items below with your own. Database IDs are not secrets, but using another environment&#39;s ID points you at the wrong target.</p></div><h2 id="_2-create-production-and-preview-d1-databases" tabindex="-1">2. Create production and preview D1 databases <a class="header-anchor" href="#_2-create-production-and-preview-d1-databases" aria-label="Permalink to “2. Create production and preview D1 databases”">​</a></h2><p>Create two, in the Cloudflare dashboard or with the CLI.</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wrangler</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> d1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> YOUR-PRODUCTION-DATABASE</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wrangler</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> d1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> YOUR-PREVIEW-DATABASE</span></span></code></pre></div><p>Use different database IDs for production and preview. Don&#39;t copy data from the preview database into production.</p><h2 id="_3-replace-the-wrangler-settings" tabindex="-1">3. Replace the Wrangler settings <a class="header-anchor" href="#_3-replace-the-wrangler-settings" aria-label="Permalink to “3. Replace the Wrangler settings”">​</a></h2><p>Set at least the following.</p><table tabindex="0"><thead><tr><th>File or location</th><th>What to set</th></tr></thead><tbody><tr><td><code>account_id</code> / <code>name</code> in wrangler.json</td><td>Your account ID and Worker name</td></tr><tr><td>The database in <code>d1_databases</code></td><td>The production database ID and name</td></tr><tr><td><code>vars.AUTH_MODE</code></td><td><code>passkey</code></td></tr><tr><td><code>vars.AUTH_ORIGIN</code></td><td>The production admin console origin, without a trailing slash</td></tr><tr><td><code>previews.vars.AUTH_ORIGIN</code></td><td>The origin of the fixed preview URL</td></tr><tr><td><code>previews.vars.DEPLOYMENT_TIER</code></td><td><code>preview</code></td></tr><tr><td><code>previews.vars.PREVIEW_MODEL_MODE</code></td><td><code>stub</code> at first</td></tr><tr><td>The database in <code>previews.d1_databases</code></td><td>The preview database ID and name</td></tr><tr><td><code>previews.durable_objects.bindings</code></td><td>MODEL_BUDGET / ModelBudget. Uses the class in the same Worker</td></tr><tr><td><code>previews.ratelimits</code></td><td>A <code>namespace_id</code> different from production</td></tr><tr><td>PREVIEW_DB in wrangler.preview-migrations.json</td><td>The same ID and name as the preview database above, and the same account_id</td></tr></tbody></table><p><code>npm run cf:configure -- &lt;D1 UUID&gt; &lt;Worker name&gt;</code> is a helper that only updates the production-side ID and Worker name. Edit <code>account_id</code>, the origin, Preview and the migration settings separately.</p><p>The current deployment script derives the Preview name from the host name of the fixed AUTH_ORIGIN. For example, with <code>review-YOUR-WORKER.YOUR-SUBDOMAIN.workers.dev</code>, the name is <code>review</code>.</p><h2 id="_4-protect-preview-with-access" tabindex="-1">4. Protect Preview with Access <a class="header-anchor" href="#_4-protect-preview-with-access" aria-label="Permalink to “4. Protect Preview with Access”">​</a></h2><p>If you use an existing Worker, continue from that Worker&#39;s settings screen. If the parent resource for a new Worker doesn&#39;t exist yet, you can first create Preview in a <strong>closed state</strong>. Leave <code>PREVIEW_ACCESS_AUD</code> and <code>PREVIEW_ACCESS_DOMAIN</code> empty and run the following. Because the Worker has no entry rule, it returns no page.</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build:cloudflare</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wrangler</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> preview</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> YOUR-PREVIEW-NAME</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --ignore-base-config</span></span></code></pre></div><p>In a Cloudflare Access application, protect <strong>only the Preview</strong> of your Worker. Limit the allowed emails and make sure Production is not included.</p><p>Set the application&#39;s audience in <code>previews.vars.PREVIEW_ACCESS_AUD</code>, and your team&#39;s authentication domain (<code>TEAM.cloudflareaccess.com</code>) in <code>PREVIEW_ACCESS_DOMAIN</code>. Take both from your actual Access settings.</p><p>The Worker also verifies the JWT&#39;s signature, issuer, audience and expiry. Without these settings it returns no page. If the Preview URL is disabled on an existing Worker, enable routing, but don&#39;t deploy unverified app code to production just for that.</p><h2 id="_5-register-the-preview-secret" tabindex="-1">5. Register the Preview secret <a class="header-anchor" href="#_5-register-the-preview-secret" aria-label="Permalink to “5. Register the Preview secret”">​</a></h2><p>The Preview AUTH_SECRET is an independent random value of at least 32 characters. Don&#39;t store it in plain variables or in Git.</p><p>For the first deployment, you can put only AUTH_SECRET into a local JSON file with restricted permissions and pass it through <code>PREVIEW_SECRETS_FILE</code>. For example, name the file <code>.dev.vars.preview-secrets.json</code>, which is excluded from Git. Replace the value with an independent random value of at least 32 characters that you generated yourself.</p><div class="language-json" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;AUTH_SECRET&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;a secret value you generated yourself&gt;&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># First-time example in a POSIX shell. Commit the settings and code first</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PREVIEW_SECRETS_FILE</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.dev.vars.preview-secrets.json</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cf:preview</span></span></code></pre></div><p>In PowerShell, set the file path in <code>$env:PREVIEW_SECRETS_FILE</code> and run the same command. Don&#39;t write the value in a command argument or a plain variable, and don&#39;t add the file to Git. After registration you can safely delete the local secrets file you no longer need.</p><p>For an existing Preview, you can also register it interactively.</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wrangler</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> preview</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> secret</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> put</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> AUTH_SECRET</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> YOUR-PREVIEW-NAME</span></span></code></pre></div><div class="info custom-block"><p class="custom-block-title">The shared base is not inherited automatically</p><p>This project&#39;s <code>cf:preview</code> uses <code>--ignore-base-config</code>. Don&#39;t assume a secret placed only in the shared Previews base will be used automatically. The Preview&#39;s own secrets are kept when you update it.</p></div><h2 id="_6-deploy-to-preview-and-check" tabindex="-1">6. Deploy to Preview and check <a class="header-anchor" href="#_6-deploy-to-preview-and-check" aria-label="Permalink to “6. Deploy to Preview and check”">​</a></h2><p>Commit your settings, empty the working tree, then run:</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:cloudflare</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:browser</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cf:preview</span></span></code></pre></div><p>This migrates the preview database, registers the initial site and deploys to Preview. Enter through Access, then register a display name and a passkey. The first user of the preview environment is fixed to the email authenticated by Access.</p><h2 id="_7-set-the-production-secrets" tabindex="-1">7. Set the production secrets <a class="header-anchor" href="#_7-set-the-production-secrets" aria-label="Permalink to “7. Set the production secrets”">​</a></h2><p>Production needs <code>ADMIN_TOKEN</code>, a runtime secret for first-time registration, and <code>JEV_KEYRING</code>, which encrypts each site&#39;s API key. Follow <a href="./../operations/jev-keys">initial setup of the encryption key</a>, and generate and register them only if no existing value is present. These are separate from the API token used to operate Cloudflare.</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wrangler</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> secret</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> put</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ADMIN_TOKEN</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># Register JEV_KEYRING with the initial setup steps above.</span></span></code></pre></div><p>After deploying to production, register the Jev API key from &quot;Jev connection (「Jev連携」)&quot; for each site in the admin console. A shared JEV_API_KEY is not needed.</p><p>If the production AUTH_SECRET doesn&#39;t exist yet, an independent value is generated and set during the explicit production release step. Don&#39;t copy the Preview value. An existing environment&#39;s value is never overwritten.</p><h2 id="_8-release-to-production-after-checking" tabindex="-1">8. Release to production after checking <a class="header-anchor" href="#_8-release-to-production-after-checking" aria-label="Permalink to “8. Release to production after checking”">​</a></h2><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cf:release</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --reviewed-commit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> FULL_40_CHARACTER_COMMIT_SHA</span></span></code></pre></div><p>Production migration and deployment run only when the conditions in <a href="./preview-production">From Preview to Production</a> are met. On the production <code>/admin</code>, register the first superuser and a passkey with the initial ADMIN_TOKEN. From then on, sign in with the passkey.</p><p>Finally, check the site settings, the <a href="./../integration/sdk">shared tag</a> and normal decisions and display.</p><h2 id="use-a-custom-domain-for-the-admin-console" tabindex="-1">Use a custom domain for the admin console <a class="header-anchor" href="#use-a-custom-domain-for-the-admin-console" aria-label="Permalink to “Use a custom domain for the admin console”">​</a></h2><p>After connecting your custom domain to the Worker in Cloudflare, also set that HTTPS origin in the plain variable <code>AUTH_ORIGIN</code>. Example: <code>https://jevsense.example.com</code>. Don&#39;t add a trailing <code>/</code> or <code>/admin</code>. The admin console opens at <code>https://jevsense.example.com/admin</code>. Reflect the setting in the repository&#39;s <code>wrangler.json</code> too, so the next deployment doesn&#39;t revert it.</p><p>If the admin console is opened over HTTP or through another connected domain, you are redirected to the configured official HTTPS URL. Authentication POST requests from another origin are not accepted. The <code>/sdk.js</code> and <code>/v1/*</code> endpoints used by SDK tags already placed on pages continue to work.</p><p>If you change the admin domain after registering passkeys, secure your recovery codes first. A passkey is bound to its domain, so you need to register again on the new domain. The initial <code>ADMIN_TOKEN</code> cannot recreate an already registered account. Use the <a href="./../guides/accounts">recovery steps</a> for the existing account.</p>`,49)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};